PREFIX ucum: <https://biomedit.ch/rdf/sphn-resource/ucum/>
PREFIX bif: <bif:>
SELECT (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?exp rdf:type sphn:Exposure .
    ?exp sphn:hasAgentCode ?exp_code .
    ?exp_code rdf:type snomed:387414008 OPTION(inference "https://biomedit.ch/rdf/sphn-resource/global") .
  }
  FILTER NOT EXISTS {
    GRAPH ?g {
      ?test rdf:type sphn:LabTest .
      ?test sphn:hasCode ?test_code .
      ?test_code rdf:type <https://loinc.org/rdf/30156-4> OPTION(inference "https://biomedit.ch/rdf/sphn-resource/global") .
    }
  }
}

